// Ce fichier centralise l'adresse de notre backend.
// Comme ça, si l'adresse change un jour, on la change ici, une seule fois,
// au lieu de la changer dans chaque composant.

import axios from 'axios';

const api = axios.create({
    baseURL: 'http://localhost:5000/api'
});

export default api;
